    71→/// - `bucket()` UDF can be used in the dataset definition for partitioning
    72→/// - Queries return correct, complete results
    73→///
    74→/// Only a single executor is used because all nodes in this in-process test share
    75→/// the same filesystem; multiple executors would race writing to the same Cayenne
    76→/// data/metadata directories during acceleration.
    77→#[tokio::test(flavor = "multi_thread")]
    78→#[cfg(not(target_os = "windows"))]
    79→async fn test_distributed_acceleration_with_bucket_partitioning() -> Result<(), anyhow::Error> {
    80→    let _ = tracing_subscriber::fmt()
    81→        .with_env_filter(EnvFilter::new("runtime=debug,info"))
    82→        .with_ansi(true)
    83→        .try_init();
    84→
    85→    for env_var in ["AWS_S3_VECTORS_KEY", "AWS_S3_VECTORS_SECRET"] {
    86→        verify_env_secret_exists(env_var)
    87→            .await
    88→            .map_err(anyhow::Error::msg)?;
    89→    }
    90→
    91→    test_request_context()
    92→        .scope(async {
    93→            let tempdir = tempfile::tempdir().expect("should create temp dir");
    94→            CryptoProvider::install_default(aws_lc_rs::default_provider())
    95→                .expect("should install aws-lc-rs");
    96→
    97→            let pki = init_pki(tempdir.path()).expect("should create PKI");
    98→            let scheduler_cert = pki
    99→                .create_client_cert("scheduler")
   100→                .expect("should create scheduler cert");
   101→            let executor1_cert = pki
   102→                .create_client_cert("executor1")
   103→                .expect("should create executor1 cert");
   104→
   105→            // Write test CSV data
   106→            let csv_path = tempdir.path().join("test_data.csv");
   107→            std::fs::write(&csv_path, TEST_DATA_CSV).expect("write test data file");
   108→            let csv_source = format!("file:{}", csv_path.display());
   109→
   110→            configure_test_datafusion();
   111→
   112→            // --- Scheduler ---
   113→            // Scheduler owns the dataset definition. The executor receives it via
   114→            // `get_app_definition` gRPC and loads Cayenne file-mode acceleration.
   115→            let scheduler_data_dir = tempdir.path().join("scheduler_data");
   116→            std::fs::create_dir_all(&scheduler_data_dir).expect("create scheduler data dir");
   117→            let scheduler_dataset =
   118→                make_accelerated_dataset(&csv_source, "test_data", 3, "id", &scheduler_data_dir);
   119→
   120→            // The scheduler requires a `runtime.scheduler` config with a
   121→            // `state_location` so that the `PartitionManager` is created.
   122→            // Without it, partition allocation to executors never happens and
   123→            // the distributed query resolves to `EmptyExec`.
   124→            let scheduler_app = AppBuilder::new("test_distributed_accel")
   125→                .with_dataset(scheduler_dataset)
   126→                .with_runtime(SpicepodRuntime {
   127→                    scheduler: Some(make_scheduler_config()),
   128→                    ..SpicepodRuntime::default()
   129→                })
   130→                .build();
   131→
   132→            let scheduler_config = Config {
   133→                http_bind_address: std::net::SocketAddr::V4(SocketAddrV4::new(
   134→                    Ipv4Addr::LOCALHOST,
   135→                    8390,
   136→                )),
   137→                flight_bind_address: std::net::SocketAddr::V4(SocketAddrV4::new(
   138→                    Ipv4Addr::LOCALHOST,
   139→                    50351,
   140→                )),
   141→                cluster: ClusterConfig {
   142→                    role: Some(runtime::config::ClusterRole::Scheduler),
   143→                    node_bind_address: std::net::SocketAddr::V4(SocketAddrV4::new(
   144→                        Ipv4Addr::LOCALHOST,
   145→                        50352,
   146→                    )),
   147→                    node_advertise_address: Some("127.0.0.1".to_string()),
   148→                    node_mtls_ca_certificate_file: Some(
   149→                        pki.ca_cert_path.to_string_lossy().to_string(),
   150→                    ),
   151→                    node_mtls_certificate_file: Some(
   152→                        scheduler_cert.cert_path.to_string_lossy().to_string(),
   153→                    ),
   154→                    node_mtls_key_file: Some(scheduler_cert.key_path.to_string_lossy().to_string()),
   155→                    ..Default::default()
   156→                },
   157→                ..Default::default()
   158→            };
   159→
   160→            let scheduler_rt = Arc::new(
   161→                Runtime::builder()
   162→                    .with_runtime_config(scheduler_config.clone())
   163→                    .with_resolved_cluster_config(
   164→                        ResolvedClusterConfig::try_new(scheduler_config.cluster.clone())
   165→                            .expect("should resolve cluster config"),
   166→                    )
   167→                    .with_app(scheduler_app)
   168→                    .build()
   169→                    .await,
   170→            );
   171→
   172→            let cloned_scheduler_rt = Arc::clone(&scheduler_rt);
   173→            let scheduler_server_thread = tokio::spawn(async move {
   174→                Box::pin(cloned_scheduler_rt.start_servers(
   175→                    scheduler_config,
   176→                    None,
   177→                    EndpointAuth::no_auth(),
   178→                ))
   179→                .await
   180→            });
   181→
   182→            tokio::select! {
   183→                () = tokio::time::sleep(Duration::from_secs(60)) => {
   184→                    return Err(anyhow::Error::msg("Timed out waiting for scheduler to start"));
   185→                }
   186→                () = Arc::clone(&scheduler_rt).load_components() => {}
   187→            }
