   189→            // Ensure the scheduler's HTTP and cluster gRPC servers are listening
   190→            // before starting the executor — otherwise the executor's
   191→            // `start_servers` → `initialize_cluster_executor` fails with a
   192→            // transport error connecting to the scheduler.
   193→            runtime_ready_check(&scheduler_rt).await;
