   205→                    Ipv4Addr::LOCALHOST,
   206→                    8391,
   207→                )),
   208→                flight_bind_address: std::net::SocketAddr::V4(SocketAddrV4::new(
   209→                    Ipv4Addr::LOCALHOST,
   210→                    50353,
   211→                )),
   212→                cluster: ClusterConfig {
   213→                    role: Some(runtime::config::ClusterRole::Executor),
   214→                    node_bind_address: std::net::SocketAddr::V4(SocketAddrV4::new(
