   216→                        50354,
   217→                    )),
   218→                    scheduler_address: Some("127.0.0.1:50352".to_string()),
   219→                    node_advertise_address: Some("127.0.0.1".to_string()),
   220→                    node_mtls_ca_certificate_file: Some(
   221→                        pki.ca_cert_path.to_string_lossy().to_string(),
   222→                    ),
   223→                    node_mtls_certificate_file: Some(
   224→                        executor1_cert.cert_path.to_string_lossy().to_string(),
   225→                    ),
   226→                    node_mtls_key_file: Some(executor1_cert.key_path.to_string_lossy().to_string()),
   227→                    ..Default::default()
   228→                },
   229→                ..Default::default()
   230→            };
   231→
   232→            let executor1_rt = Arc::new(
   233→                Runtime::builder()
   234→                    .with_runtime_config(executor1_config.clone())
   235→                    .with_resolved_cluster_config(
   236→                        ResolvedClusterConfig::try_new(executor1_config.cluster.clone())
   237→                            .expect("should resolve cluster config"),
   238→                    )
   239→                    .with_app(executor1_app)
   240→                    .build()
   241→                    .await,
   242→            );
   243→
   244→            let cloned_executor1_rt = Arc::clone(&executor1_rt);
   245→            let mut executor1_server_thread = tokio::spawn(async move {
   246→                Box::pin(cloned_executor1_rt.start_servers(
   247→                    executor1_config,
   248→                    None,
   249→                    EndpointAuth::no_auth(),
   250→                ))
   251→                .await
   252→            });
   253→
   254→            tokio::select! {
   255→                () = tokio::time::sleep(Duration::from_secs(60)) => {
   256→                    return Err(anyhow::Error::msg("Timed out waiting for executor1 to start"));
   257→                }
   258→                result = &mut executor1_server_thread => {
   259→                    match result {
   260→                        Ok(Ok(())) => return Err(anyhow::Error::msg("Executor1 server thread finished unexpectedly")),
   261→                        Ok(Err(e)) => return Err(anyhow::Error::msg(format!("Executor1 server failed to start: {e}"))),
   262→                        Err(e) => return Err(anyhow::Error::msg(format!("Executor1 server thread panicked: {e}"))),
   263→                    }
   264→                }
   265→                () = Arc::clone(&executor1_rt).load_components() => {}
   266→            }
   267→
   268→            runtime_ready_check(&executor1_rt).await;
   269→
   270→            // Wait for the executor to register with the scheduler
   271→            let scheduler_server = scheduler_rt
   272→                .datafusion()
   273→                .scheduler_server
   274→                .read()
   275→                .expect("scheduler server lock")
   276→                .clone()
   277→                .expect("scheduler server should be available");
   278→            let executor_manager = scheduler_server.state.executor_manager.clone();
   279→
   280→            wait_for_executor_count(&executor_manager, 1, Duration::from_secs(15)).await?;
   281→
   282→            // Wait for executor acceleration to complete. The executor loads datasets asynchronously after connecting to the scheduler
   283→            sleep(Duration::from_secs(5)).await;
   284→
   285→            // Test 1: SELECT all rows
   286→            let query = QueryBuilder::new(
   287→                "SELECT id, name, age, city, score FROM test_data ORDER BY id",
   288→                scheduler_rt.datafusion(),
   289→            );
   290→            let result = query.build().run().await.map_err(|e| {
   291→                anyhow::Error::msg(format!("Query 'select all' failed: {e}"))
   292→            })?;
   293→            let results: Vec<RecordBatch> = result.data.try_collect().await.map_err(|e| {
   294→                anyhow::Error::msg(format!("Query 'select all' stream failed: {e}"))
   295→            })?;
   296→
   297→            let pretty = arrow::util::pretty::pretty_format_batches(&results)
   298→                .map_err(|e| anyhow::Error::msg(e.to_string()))
   299→                .expect("Should format batches");
   300→            insta::assert_snapshot!("distributed_accel_select_all", pretty);
   301→
   302→            // Test 2: Aggregation query — tests distributed GROUP BY with accelerated data
   303→            let query = QueryBuilder::new(
   304→                "SELECT COUNT(*) as total_rows, AVG(score) as avg_score, MIN(age) as min_age, MAX(age) as max_age FROM test_data",
   305→                scheduler_rt.datafusion(),
   306→            );
   307→            let result = query.build().run().await.map_err(|e| {
   308→                anyhow::Error::msg(format!("Query 'aggregation' failed: {e}"))
   309→            })?;
   310→            let results: Vec<RecordBatch> = result.data.try_collect().await.map_err(|e| {
   311→                anyhow::Error::msg(format!("Query 'aggregation' stream failed: {e}"))
   312→            })?;
   313→
   314→            let pretty = arrow::util::pretty::pretty_format_batches(&results)
   315→                .map_err(|e| anyhow::Error::msg(e.to_string()))
   316→                .expect("Should format batches");
   317→            insta::assert_snapshot!("distributed_accel_aggregation", pretty);
   318→
   319→            // Cleanup
   320→            executor1_rt.shutdown().await;
   321→            drop(executor1_rt);
   322→            executor1_server_thread.abort();
   323→
   324→            let _ = wait_for_executor_count(&executor_manager, 0, Duration::from_secs(10)).await;
   325→
   326→            scheduler_rt.shutdown().await;
   327→            drop(scheduler_rt);
   328→            scheduler_server_thread.abort();
   329→
   330→            tokio::time::sleep(Duration::from_secs(2)).await;
   331→
   332→            Ok(())
   333→        })
   334→        .await
   335→}
   336→
   337→async fn wait_for_port(addr: &str, timeout: Duration) {
   338→    let start = Instant::now();
   339→    while start.elapsed() < timeout {
   340→        if tokio::net::TcpStream::connect(addr).await.is_ok() {
   341→            return;
   342→        }
   343→        sleep(Duration::from_millis(100)).await;
   344→    }
   345→}
   346→
   347→async fn wait_for_executor_count(
   348→    executor_manager: &ExecutorManager,
   349→    expected: usize,
   350→    timeout: Duration,
   351→) -> Result<(), anyhow::Error> {
   352→    let start = Instant::now();
   353→    loop {
   354→        let count = executor_manager
   355→            .get_executor_state()
   356→            .await
   357→            .map_err(|err| anyhow::Error::msg(err.to_string()))?
   358→            .len();
   359→        if count == expected {
   360→            return Ok(());
   361→        }
   362→        if start.elapsed() > timeout {
   363→            return Err(anyhow::Error::msg(format!(
   364→                "Timed out waiting for {expected} executors; found {count}"
   365→            )));
   366→        }
   367→        sleep(Duration::from_millis(200)).await;
   368→    }
   369→}
   370→
   371→/// Return a `SchedulerConfig` pointing at an S3 bucket for partition state.
   372→///
   373→/// `PartitionManager` uses OCC (optimistic concurrency control) which needs
   374→/// conditional-put support (`PutMode::Update`); the local filesystem `ObjectStore`
   375→/// does not support this, so S3 is required.
   376→fn make_scheduler_config() -> SchedulerConfig {
   377→    SchedulerConfig {
   378→        state_location: "s3://spiceai-integration-tests/cluster-state/test_distributed_acceleration_with_bucket_partitioning/".to_string(),
   379→        params: Some(spicepod::param::Params::from_string_map(
   380→            std::collections::HashMap::from([
   381→                ("s3_region".to_string(), "us-east-1".to_string()),
   382→                ("s3_key".to_string(), "${env:AWS_S3_VECTORS_KEY}".to_string()),
   383→                (
   384→                    "s3_secret".to_string(),
   385→                    "${env:AWS_S3_VECTORS_SECRET}".to_string(),
   386→                ),
   387→                ("s3_auth".to_string(), "key".to_string()),
   388→            ]),
   389→        )),
   390→        partition_management: None,
   391→    }
   392→}
   393→
   394→/// Create a dataset configured with Cayenne file-mode acceleration and `bucket()` partitioning.
   395→///
   396→/// Uses explicit `cayenne_file_path` and `cayenne_metadata_dir` so that each runtime in
   397→/// a single-process test gets its own data/metadata directories without contention.
   398→fn make_accelerated_dataset(
   399→    source_path: &str,
   400→    name: &str,
   401→    num_buckets: i64,
   402→    partition_column: &str,
   403→    data_dir: &std::path::Path,
   404→) -> Dataset {
   405→    let mut dataset = Dataset::new(source_path, name);
   406→
   407→    dataset.acceleration = Some(Acceleration {
   408→        enabled: true,
   409→        engine: Some("cayenne".to_string()),
   410→        mode: Mode::File,
   411→        refresh_mode: Some(RefreshMode::Full),
   412→        partition_by: vec![PartitionedBy {
   413→            name: "expr0".to_string(),
   414→            expression: format!("bucket({num_buckets}, {partition_column})"),
   415→        }],
   416→        params: Some(spicepod::param::Params::from_string_map(
   417→            std::collections::HashMap::from([
   418→                (
   419→                    "cayenne_file_path".to_string(),
   420→                    data_dir.join("data").to_string_lossy().to_string(),
   421→                ),
   422→                (
   423→                    "cayenne_metadata_dir".to_string(),
   424→                    data_dir.join("metadata").to_string_lossy().to_string(),
   425→                ),
   426→            ]),
   427→        )),
   428→        ..Acceleration::default()
   429→    });
   430→
   431→    dataset
   432→}
