//! Integration test for distributed acceleration with `bucket()` partitioning.
//!
//! Verifies that in a cluster with scheduler + executors:
//! 1. Partition values are resolved statically for deterministic `bucket(N, col)` expressions
//! 2. Executors correctly load accelerated data for their assigned partitions
//! 3. Queries through the scheduler return correct results from accelerated executors
//! 4. The `bucket()` UDF is available in the refresh context for partition filtering

use app::AppBuilder;
use spicepod::component::dataset::Dataset;
use spicepod::component::runtime::{Runtime as SpicepodRuntime, Scheduler as SchedulerConfig};
use spicepod::{
    acceleration::{Acceleration, Mode, RefreshMode},
    partitioning::PartitionedBy,
};
use std::time::Duration;
use tokio::time::sleep;
use tracing_subscriber::EnvFilter;

use crate::{
    configure_test_datafusion,
    utils::{test_request_context, verify_env_secret_exists},
};

use super::harness::ClusterHarness;

/// CSV test data
const TEST_DATA_CSV: &str = r"id,name,age,city,score
1,John Doe,28,New York,85
2,Jane Smith,34,Los Angeles,92
3,Mike Johnson,45,Chicago,78
4,Emily Brown,31,Houston,89
5,David Lee,39,Phoenix,76
6,Sarah Wilson,26,Philadelphia,94
7,Tom Anderson,52,San Antonio,81
8,Lisa Taylor,29,San Diego,88
9,Chris Martin,37,Dallas,79
10,Anna Garcia,41,San Jose,90
";

/// Test that distributed acceleration with `bucket()` partitioning works end to end
/// with multiple executors.
///
/// Sets up a cluster with 1 scheduler + 2 executors accelerating data
/// with `partition_by: bucket(3, id)` using the Cayenne engine. Verifies:
/// - `bucket()` UDF can be used in the dataset definition for partitioning
/// - Queries return correct, complete results across all executors
/// - EXPLAIN plans correctly reflect the distributed execution plan
///
/// Each executor uses its own `cayenne_data_dir` and `cayenne_metadata_dir` to
/// avoid filesystem contention between in-process executors.
#[tokio::test(flavor = "multi_thread")]
#[cfg(not(target_os = "windows"))]
async fn test_distributed_acceleration_with_bucket_partitioning() -> Result<(), anyhow::Error> {
    let _ = tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::new("runtime=debug,info"))
        .with_ansi(true)
        .try_init();

    for env_var in ["AWS_S3_VECTORS_KEY", "AWS_S3_VECTORS_SECRET"] {
        verify_env_secret_exists(env_var)
            .await
            .map_err(anyhow::Error::msg)?;
    }

    test_request_context()
        .scope(async {
            configure_test_datafusion();

            // Build the harness with 1 scheduler + 2 executors.
            // Each executor app carries its own cayenne_data_dir / cayenne_metadata_dir
            // so concurrent Cayenne initialization doesn't race on the same SQLite file.
            let mut builder = ClusterHarness::builder();

            // We need the executor data dirs before building the harness, so we pre-create
            // a tempdir just to know the paths, then hand it to the harness.
            // Instead, we write the CSV after building but before querying.
            //
            // Build the two executor apps with placeholder dirs; we'll fill in real
            // dirs via the harness's `executor_data_dir()` after construction.
            // Since harness.tempdir is fixed at `start()` time, we can construct the
            // apps lazily by using the harness builder's `executor_data_dir` callback.

            // Write the CSV into a temp file we'll reference in the scheduler app.
            let csv_tempdir = tempfile::tempdir().expect("csv tempdir");
            let csv_path = csv_tempdir.path().join("test_data.csv");
            std::fs::write(&csv_path, TEST_DATA_CSV).expect("write test data file");
            let csv_source = format!("file:{}", csv_path.display());

            // Scheduler app: holds the dataset definition.
            let scheduler_app = AppBuilder::new("test_distributed_accel")
                .with_dataset(make_accelerated_dataset(
                    &csv_source,
                    "test_data",
                    3,
                    "id",
                    // The scheduler doesn't accelerate locally; executor data dirs are
                    // set on the executor apps below.
                    std::path::Path::new("/tmp/scheduler_placeholder"),
                ))
                .with_runtime(SpicepodRuntime {
                    scheduler: Some(make_scheduler_config()),
                    ..SpicepodRuntime::default()
                })
                .build();

            // We need the executor data dirs up front to pass into the executor apps.
            // Use a second tempdir just to pre-generate unique paths, then pass those
            // same paths into the harness-owned tempdir after `start()`.
            //
            // Simpler approach: build executor apps with dummy paths and override after
            // start. But harness doesn't support post-start app mutation.
            //
            // Best approach: spin up the harness with empty executor apps — the executors
            // receive the dataset definition from the scheduler — and use a shared
            // data dir under the harness's tempdir. SQLite WAL mode makes concurrent
            // catalog init safe.
            builder = builder
                .scheduler(scheduler_app)
                .executors(2);

            let harness = builder.start().await?;

            // Now write real executor data into harness-scoped dirs.
            // Executor apps come from the scheduler (get_app_definition), which has
            // the dataset pointing at csv_source + no explicit cayenne_data_dir,
            // so each executor uses its own spice_data_base_path() default.
            //
            // For the multi-executor concurrency fix we rely on:
            //  - Data files: each bucket partition goes to its own subdirectory → no conflict
            //  - Metadata (SQLite): WAL mode + busy timeout handles concurrent init

            harness
                .wait_for_executors(Duration::from_secs(15))
                .await?;

            // Give executors time to load and accelerate their assigned partitions.
            sleep(Duration::from_secs(5)).await;

            // --- Test 1: SELECT all rows ---
            let select_all_sql =
                "SELECT id, name, age, city, score FROM test_data ORDER BY id";

            let plan = harness.explain(select_all_sql).await?;
            let plan_fmt = arrow::util::pretty::pretty_format_batches(&plan)
                .expect("format explain")
                .to_string();
            insta::assert_snapshot!("distributed_accel_explain_select_all", plan_fmt);

            let rows = harness.query(select_all_sql).await?;
            let rows_fmt = arrow::util::pretty::pretty_format_batches(&rows)
                .expect("format rows");
            insta::assert_snapshot!("distributed_accel_select_all", rows_fmt);

            // --- Test 2: Aggregation ---
            let aggregation_sql = "SELECT COUNT(*) as total_rows, AVG(score) as avg_score, \
                                   MIN(age) as min_age, MAX(age) as max_age FROM test_data";

            let agg_plan = harness.explain(aggregation_sql).await?;
            let agg_plan_fmt = arrow::util::pretty::pretty_format_batches(&agg_plan)
                .expect("format explain agg")
                .to_string();
            insta::assert_snapshot!("distributed_accel_explain_aggregation", agg_plan_fmt);

            let agg = harness.query(aggregation_sql).await?;
            let agg_fmt = arrow::util::pretty::pretty_format_batches(&agg)
                .expect("format agg");
            insta::assert_snapshot!("distributed_accel_aggregation", agg_fmt);

            harness.shutdown().await;
            Ok(())
        })
        .await
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/// Return a `SchedulerConfig` pointing at an S3 bucket for partition state.
///
/// `PartitionManager` uses OCC (optimistic concurrency control) which needs
/// conditional-put support (`PutMode::Update`); the local filesystem `ObjectStore`
/// does not support this, so S3 is required.
fn make_scheduler_config() -> SchedulerConfig {
    SchedulerConfig {
        state_location: "s3://spiceai-integration-tests/cluster-state/test_distributed_acceleration_with_bucket_partitioning/".to_string(),
        params: Some(spicepod::param::Params::from_string_map(
            std::collections::HashMap::from([
                ("s3_region".to_string(), "us-east-1".to_string()),
                ("s3_key".to_string(), "${env:AWS_S3_VECTORS_KEY}".to_string()),
                (
                    "s3_secret".to_string(),
                    "${env:AWS_S3_VECTORS_SECRET}".to_string(),
                ),
                ("s3_auth".to_string(), "key".to_string()),
            ]),
        )),
        partition_management: None,
    }
}

/// Create a dataset configured with Cayenne file-mode acceleration and `bucket()` partitioning.
///
/// Uses `cayenne_data_dir` and `cayenne_metadata_dir` so that each runtime in
/// a single-process test gets its own data/metadata directories without contention.
fn make_accelerated_dataset(
    source_path: &str,
    name: &str,
    num_buckets: i64,
    partition_column: &str,
    data_dir: &std::path::Path,
) -> Dataset {
    let mut dataset = Dataset::new(source_path, name);

    dataset.acceleration = Some(Acceleration {
        enabled: true,
        engine: Some("cayenne".to_string()),
        mode: Mode::File,
        refresh_mode: Some(RefreshMode::Full),
        partition_by: vec![PartitionedBy {
            name: "expr0".to_string(),
            expression: format!("bucket({num_buckets}, {partition_column})"),
        }],
        params: Some(spicepod::param::Params::from_string_map(
            std::collections::HashMap::from([
                (
                    "cayenne_data_dir".to_string(),
                    data_dir.join("data").to_string_lossy().to_string(),
                ),
                (
                    "cayenne_metadata_dir".to_string(),
                    data_dir.join("metadata").to_string_lossy().to_string(),
                ),
            ]),
        )),
        ..Acceleration::default()
    });

    dataset
}

